fun FlowContent.orderForm(codename: String = "", invalid: Boolean = false) {
    val field = no.lotek.Lt.field(id = "$codename$", required = no.lotek.RequiredMarker.SYMBOL, error = true, invalid = invalid)
    form(action = "/jobs", method = FormMethod.post) {
        id = "$order_form$"
        attributes["novalidate"] = ""
        label { lt(field.label); +"Codename" }
        input {
            lt(no.lotek.Lt.input(type = no.lotek.InputType.TEXT), field.control)
            name = "$codename$"
            required = true
            // What the user typed comes back, so a failed submission loses nothing.
            if (codename.isNotEmpty()) value = codename
            if (invalid) autoFocus = true
        }
        p { lt(no.lotek.Lt.errorText(), field.error); +"Enter a codename." }
        button { lt(no.lotek.Lt.button()); type = ButtonType.submit; +"Order the job" }
    }
}

data class Part(val key: String, val title: String, val text: String)

fun FlowContent.claimTabs(
    parts: List<Part> = listOf(
        Part("claim", "Claim", "Claim AV-2079-0481 was filed on 4 March 2079."),
        Part("attachments", "Attachments", "Three attachments have been received. The death certificate arrived on 6 March."),
    ),
) {
    val tabs = no.lotek.Lt.tabs(id = "$claim_tabs$", keys = parts.map { it.key }, label = "Parts of the claim")
    ltTabs {
        id = "$claim_tabs$"
        ul {
            lt(tabs.list)
            parts.zip(tabs.tabs).forEach { (part, tab) -> li { a { lt(tab); +part.title } } }
        }
        for ((i, part) in parts.withIndex()) {
            section {
                lt(tabs.panels[i])
                h2 { lt(tabs.headings[i]); +part.title }
                p { +part.text }
            }
        }
    }
}

data class Fault(val field: String, val message: String)

fun FlowContent.orderForm(fixer: String = "", faults: List<Fault> = emptyList()) {
    val summary = no.lotek.Lt.errorSummary(count = faults.size, id = "$errors$")
    val field = no.lotek.Lt.field(id = "$fixer$", invalid = faults.any { it.field == "$fixer$" })
    form(action = "/jobs", method = FormMethod.post) {
        attributes["novalidate"] = ""
        ltErrorSummary {
            lt(summary.host)
            h2 {
                lt(summary.title)
                if (faults.isNotEmpty()) +(if (faults.size == 1) "The form has one error" else "The form has $${faults.size} errors")
            }
            ul {
                lt(no.lotek.Lt.list())
                for (fault in faults) li { a(href = "#$${fault.field}") { +fault.message } }
            }
        }
        label { lt(field.label); +"Fixer's address" }
        input {
            lt(no.lotek.Lt.input(type = no.lotek.InputType.EMAIL), field.control)
            name = "$fixer$"
            // What the user typed comes back, so a failed submission loses nothing.
            if (fixer.isNotEmpty()) value = fixer
        }
        button { lt(no.lotek.Lt.button()); +"Order the job" }
    }
}

fun FlowContent.actionsMenu() {
    val menu = no.lotek.Lt.popover(id = "$actions$", placement = no.lotek.PopoverPlacement.BOTTOM_END)
    ltPopover {
        id = "$menu$"
        lt(menu.host)
        button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY), menu.trigger); type = ButtonType.button; +"Actions" }
        ul {
            lt(menu.panel)
            li {
                form(action = "/loans/LDG-117/return", method = FormMethod.post) {
                    button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.GHOST)); +"Mark LDG-117 returned" }
                }
            }
            li {
                form(action = "/loans/LDG-117/late-fee", method = FormMethod.post) {
                    button { lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.GHOST)); +"Charge the late fee" }
                }
            }
        }
    }
}

fun FlowContent.policyTerms() {
    val actOfGod = no.lotek.Lt.term(id = "$term_act_of_god$")
    p {
        +"A claim is paid out unless the death was an "
        ltTerm { a { lt(actOfGod.word); +"act of God" } }
        +"."
    }
    h2 { +"Glossary" }
    dl {
        ltTermEntry(actOfGod.entry) {
            dt { +"Act of God" }
            dd { +"A cause of death the policy does not cover. The insurer can add to the list without notice." }
        }
    }
}

data class Breaker(val code: String, val name: String)

fun FlowContent.breakerSearch(
    breakers: List<Breaker> = listOf(Breaker("crowbar", "Crowbar"), Breaker("needle", "Needle")),
) {
    val search = no.lotek.Lt.suggestion(id = "$breaker$", keys = breakers.map { it.code })
    ltSuggestion {
        id = "$breaker_search$"
        label { lt(search.label); +"Breaker" }
        input { lt(search.control); name = "$breaker$" }
        ul {
            lt(search.list)
            breakers.zip(search.options).forEach { (breaker, option) -> li { lt(option); +breaker.name } }
        }
        p { lt(search.empty); +"No matches" }
        span { lt(search.status) }
    }
}

fun FlowContent.cancelJob(open: Boolean = true) {
    val box = no.lotek.Lt.dialog(titleId = "$confirm_title$", open = open)
    ltDialog {
        lt(box.host)
        id = "$confirm$"
        dialog {
            lt(box.dialog)
            // Escape is a close request, reported with `cancel`, and it
            // keeps the job. A close the server makes gives no `cancel`.
            attributes["data-on:cancel"] = "@post('/jobs/222-0481/keep')"
            h2 { lt(box.title); +"Cancel job 222-0481?" }
            div {
                lt(box.body)
                p { +"The crew keeps the advance. This cannot be undone." }
            }
            form {
                lt(box.footer)
                attributes["method"] = "dialog"
                button {
                    lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY))
                    value = "keep"
                    attributes["data-on:click"] = "@post('/jobs/222-0481/keep')"
                    +"Keep the job"
                }
                button {
                    lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.DANGER))
                    value = "cancel"
                    attributes["data-on:click"] = "@post('/jobs/222-0481/cancel')"
                    +"Cancel the job"
                }
            }
        }
    }
}

fun FlowContent.relay() {
    ltToast { lt(no.lotek.Lt.toast(label = "Messages").host); id = "$messages$" }
    button {
        lt(no.lotek.Lt.button())
        type = ButtonType.button
        attributes["data-on:click"] = "@post('/relays/14/restart')"
        +"Restart relay 14"
    }
}

fun FlowContent.sessionWarning() {
    val session = no.lotek.Lt.sessionTimeout(titleId = "$session_title$", warnAt = 1500, expiresAt = 1800)
    ltSessionTimeout {
        lt(session.host)
        attributes["data-on:session-extend"] = "@post('/api/extend-session')"
        attributes["data-on:session-expired"] = "window.location = '/log-in?reason=expired'"
        dialog {
            lt(session.dialog)
            h2 { lt(session.title); +"Your session is ending" }
            p {
                lt(session.text)
                +"Your session on the Lattice ends in "
                span { lt(session.count) }
                +". Unsaved routes will be lost."
            }
            span { lt(session.live) }
            form {
                lt(session.actions)
                attributes["method"] = "dialog"
                button { lt(no.lotek.Lt.button(), session.extend); +"Stay connected" }
                button {
                    lt(no.lotek.Lt.button(variant = no.lotek.ButtonVariant.SECONDARY), session.logout)
                    // Logging out is a post to the server, which ends the session.
                    formMethod = ButtonFormMethod.post
                    formAction = "/log-out"
                    +"Log out"
                }
            }
        }
    }
}

fun FlowContent.connection() {
    ltConnectionStatus {
        lt(no.lotek.Lt.connectionStatus())
        // `retrying`: the request got no answer. `error`: an answer of 400 or
        // more; 502, 503 and 504 come from a gateway whose server is gone,
        // any other is a server that is there. A patch: the stream is alive.
        attributes["data-on:datastar-fetch__document"] =
            "evt.detail.type === 'retrying' || [502, 503, 504].includes(+evt.detail.argsRaw.status) ? el.reportFailure() : (evt.detail.type === 'error' || evt.detail.type.startsWith('datastar-patch')) && el.reportSuccess()"
    }
}
